      "desc": "文化大革命时期任中央文革小组副组长、中共中央政治局常委，是党内重要的理论家，参与并主导上海「一月风暴」与上海的接管建设，对「无产阶级专政下继续革命」等理论有系统阐发。1976 年 10 月被隔离审查，1981 年被特别法庭认定为「林彪、江青反革命集团」案主犯——此为官方定性；对其理论贡献与革命立场，也多有好评，主张重新评价其历史功过。",
