      "bg": "1903 年 7—8 月，先在布鲁塞尔、后移至伦敦召开。此前《火星报》派与「经济派」的论战（《怎么办？》1902）已划清理论界限。大会主要议题是党纲、党章与组织问题。",
      "impact": "在党章第一条（党员条件）上分裂：列宁主张必须参加党的一个组织，马尔托夫主张不必。选举中央机关时列宁派获多数，遂称布尔什维克（多数派），马尔托夫派称孟什维克（少数派）。两派于 1912 年布拉格会议后彻底分立。"
