      "bg": "1918—1921 年国内战争与外国武装干涉，苏维埃政权控制区粮食严重短缺，城市人口锐减。为保障红军与城市供应，实行余粮收集制、工业普遍国有化、实物配给制、普遍劳动义务制，并禁止私人贸易。",
