      "desc": "1942 年至 1945 年中国共产党在延安开展的全党整风运动。1942 年 2 月毛泽东作《整顿党的作风》《反对党八股》讲演，运动以反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整顿文风为主要内容，方针是「惩前毖后，治病救人」。1942 年 5 月召开延安文艺座谈会。1943 年审查干部工作中一度出现扩大化，随后纠正。1945 年 4 月中共六届七中全会通过《关于若干历史问题的决议》，对党内历次「左」右倾错误作出总结，为中共七大召开准备了思想条件。",
